select public.import_problem_records($seed$[{"id": "demo-01", "contest_name": "Original Demonstration Set", "question_number": 1, "category": "Algebra", "difficulty_rating": 1200, "question_latex": "Define a binary operation $\\#$ on the integers by $m \\# n = m^2 - n$. Find $2 \\# (0 \\# (2 \\# 5))$.", "options": [{"label": "A", "text": "-1"}, {"label": "B", "text": "0"}, {"label": "C", "text": "1"}, {"label": "D", "text": "3"}, {"label": "E", "text": "5"}], "correct_answer": "D", "figure_required": false, "figure_image_path": null, "written_solution": "Evaluate inside out: First, $2 \\# 5 = 2^2 - 5 = -1$. Next, $0 \\# (-1) = 0^2 - (-1) = 1$. Finally, $2 \\# 1 = 2^2 - 1 = 3$.", "calculator_trick": {"model": "Casio FX-115ES PLUS", "applicable": true, "summary": "Direct evaluation on a scientific calculator.", "steps": ["Type 2^2 - 5 and hit [=] (Output: -1)", "Type 0^2 - Ans and hit [=] (Output: 1)", "Type 2^2 - Ans and hit [=] (Output: 3)"]}, "title": "Nested Operations", "topic_tags": ["Algebra"], "verification_status": "fully_verified", "source_question_file": null, "source_answer_key_file": null, "publication_status": "published", "difficulty": "Easy"}, {"id": "demo-02", "contest_name": "Original Demonstration Set", "question_number": 2, "category": "Geometry", "difficulty_rating": 1450, "question_latex": "In the given semicircle, $AC$ is perpendicular to $BD$, $|AB| = a$, and $|BC| = 1$. Find $|BD|$.", "options": [{"label": "A", "text": "$a$"}, {"label": "B", "text": "$\\sqrt{a} + 1$"}, {"label": "C", "text": "$\\sqrt{a} - 1$"}, {"label": "D", "text": "$a - 1$"}, {"label": "E", "text": "$\\sqrt{a}$"}], "correct_answer": "E", "figure_required": true, "figure_image_path": "/images/semicircle.svg", "written_solution": "Because $\\angle ADC = 90^\\circ$ and altitude $BD \\perp AC$, by the geometric mean theorem: $BD^2 = AB \\times BC = a \\times 1 = a \\implies BD = \\sqrt{a}$.", "calculator_trick": {"model": "Casio FX-115ES PLUS", "applicable": false, "summary": "This problem is best approached analytically.", "steps": []}, "title": "Altitude and Geometric Mean", "topic_tags": ["Geometry"], "verification_status": "fully_verified", "source_question_file": null, "source_answer_key_file": null, "publication_status": "published", "difficulty": "Medium"}, {"id": "demo-03", "contest_name": "Original Demonstration Set", "question_number": 3, "category": "Algebra", "difficulty_rating": 1050, "question_latex": "If $3x+7=22$, what is $x$?", "options": [{"label": "A", "text": "3"}, {"label": "B", "text": "4"}, {"label": "C", "text": "5"}, {"label": "D", "text": "6"}, {"label": "E", "text": "7"}], "correct_answer": "C", "figure_required": false, "figure_image_path": null, "written_solution": "Subtract $7$ to get $3x=15$, then divide by $3$.", "calculator_trick": {"model": "Casio FX-115ES PLUS", "applicable": true, "summary": "Direct evaluation on a scientific calculator.", "steps": ["Type (22 - 7) \u00f7 3 [=] \u2192 5"]}, "title": "Linear Equation", "topic_tags": ["Algebra"], "verification_status": "fully_verified", "source_question_file": null, "source_answer_key_file": null, "publication_status": "published", "difficulty": "Easy"}, {"id": "demo-04", "contest_name": "Original Demonstration Set", "question_number": 4, "category": "Number Theory", "difficulty_rating": 1550, "question_latex": "What is the remainder when $7^{2026}$ is divided by $10$?", "options": [{"label": "A", "text": "1"}, {"label": "B", "text": "3"}, {"label": "C", "text": "5"}, {"label": "D", "text": "7"}, {"label": "E", "text": "9"}], "correct_answer": "E", "figure_required": false, "figure_image_path": null, "written_solution": "The last digits repeat $7,9,3,1$ every four powers. Since $2026\\equiv2\\pmod4$, the remainder is $9$.", "calculator_trick": {"model": "Casio FX-115ES PLUS", "applicable": false, "summary": "This problem is best approached analytically.", "steps": []}, "title": "Last Digit Cycle", "topic_tags": ["Number Theory"], "verification_status": "fully_verified", "source_question_file": null, "source_answer_key_file": null, "publication_status": "published", "difficulty": "Medium"}, {"id": "demo-05", "contest_name": "Original Demonstration Set", "question_number": 5, "category": "Probability and Combinatorics", "difficulty_rating": 1350, "question_latex": "Two fair six-sided dice are rolled. What is the probability their sum is $8$?", "options": [{"label": "A", "text": "$1/6$"}, {"label": "B", "text": "$5/36$"}, {"label": "C", "text": "$1/4$"}, {"label": "D", "text": "$7/36$"}, {"label": "E", "text": "$1/3$"}], "correct_answer": "B", "figure_required": false, "figure_image_path": null, "written_solution": "The favorable ordered outcomes are $(2,6),(3,5),(4,4),(5,3),(6,2)$ out of $36$.", "calculator_trick": {"model": "Casio FX-115ES PLUS", "applicable": true, "summary": "Direct evaluation on a scientific calculator.", "steps": ["Type 5 \u00f7 36 [=] \u2192 5/36"]}, "title": "Dice Sum", "topic_tags": ["Probability and Combinatorics"], "verification_status": "fully_verified", "source_question_file": null, "source_answer_key_file": null, "publication_status": "published", "difficulty": "Easy"}, {"id": "demo-06", "contest_name": "Original Demonstration Set", "question_number": 6, "category": "Geometry", "difficulty_rating": 1100, "question_latex": "A right triangle has legs of length $6$ and $8$. What is its hypotenuse?", "options": [{"label": "A", "text": "9"}, {"label": "B", "text": "10"}, {"label": "C", "text": "12"}, {"label": "D", "text": "14"}, {"label": "E", "text": "16"}], "correct_answer": "B", "figure_required": false, "figure_image_path": null, "written_solution": "By Pythagoras, $c=\\sqrt{6^2+8^2}=\\sqrt{100}=10$.", "calculator_trick": {"model": "Casio FX-115ES PLUS", "applicable": true, "summary": "Direct evaluation on a scientific calculator.", "steps": ["Type \u221a(6\u00b2 + 8\u00b2) [=] \u2192 10"]}, "title": "Pythagorean Triple", "topic_tags": ["Geometry"], "verification_status": "fully_verified", "source_question_file": null, "source_answer_key_file": null, "publication_status": "published", "difficulty": "Easy"}, {"id": "demo-07", "contest_name": "Original Demonstration Set", "question_number": 7, "category": "Trigonometry and Precalculus", "difficulty_rating": 1250, "question_latex": "What is $\\sin(\\pi/6)+\\cos(\\pi/3)$?", "options": [{"label": "A", "text": "$0$"}, {"label": "B", "text": "$1/2$"}, {"label": "C", "text": "$1$"}, {"label": "D", "text": "$\\sqrt{3}$"}, {"label": "E", "text": "$2$"}], "correct_answer": "C", "figure_required": false, "figure_image_path": null, "written_solution": "Both terms equal $1/2$, so their sum is $1$.", "calculator_trick": {"model": "Casio FX-115ES PLUS", "applicable": true, "summary": "Direct evaluation on a scientific calculator.", "steps": ["Set angle mode to RAD", "Type sin(\u03c0 \u00f7 6) + cos(\u03c0 \u00f7 3) [=] \u2192 1"]}, "title": "Special Angles", "topic_tags": ["Trigonometry and Precalculus"], "verification_status": "fully_verified", "source_question_file": null, "source_answer_key_file": null, "publication_status": "published", "difficulty": "Easy"}, {"id": "demo-08", "contest_name": "Original Demonstration Set", "question_number": 8, "category": "Algebra", "difficulty_rating": 1700, "question_latex": "The roots of $x^2-5x+6=0$ are $r$ and $s$. Find $r^2+s^2$.", "options": [{"label": "A", "text": "5"}, {"label": "B", "text": "11"}, {"label": "C", "text": "13"}, {"label": "D", "text": "25"}, {"label": "E", "text": "36"}], "correct_answer": "C", "figure_required": false, "figure_image_path": null, "written_solution": "By Vieta, $r+s=5$ and $rs=6$. Thus $r^2+s^2=(r+s)^2-2rs=25-12=13$.", "calculator_trick": {"model": "Casio FX-115ES PLUS", "applicable": true, "summary": "Direct evaluation on a scientific calculator.", "steps": ["Type 5\u00b2 - 2 \u00d7 6 [=] \u2192 13"]}, "title": "Root Identities", "topic_tags": ["Algebra"], "verification_status": "fully_verified", "source_question_file": null, "source_answer_key_file": null, "publication_status": "published", "difficulty": "Medium"}, {"id": "demo-09", "contest_name": "Original Demonstration Set", "question_number": 9, "category": "Probability and Combinatorics", "difficulty_rating": 1350, "question_latex": "How many ways can three students be chosen from a group of eight?", "options": [{"label": "A", "text": "24"}, {"label": "B", "text": "48"}, {"label": "C", "text": "56"}, {"label": "D", "text": "64"}, {"label": "E", "text": "336"}], "correct_answer": "C", "figure_required": false, "figure_image_path": null, "written_solution": "$\\binom83=8\\cdot7\\cdot6/(3\\cdot2\\cdot1)=56$.", "calculator_trick": {"model": "Casio FX-115ES PLUS", "applicable": true, "summary": "Direct evaluation on a scientific calculator.", "steps": ["Type (8 \u00d7 7 \u00d7 6) \u00f7 (3 \u00d7 2 \u00d7 1) [=] \u2192 56"]}, "title": "Choose a Committee", "topic_tags": ["Probability and Combinatorics"], "verification_status": "fully_verified", "source_question_file": null, "source_answer_key_file": null, "publication_status": "published", "difficulty": "Easy"}, {"id": "demo-10", "contest_name": "Original Demonstration Set", "question_number": 10, "category": "Number Theory", "difficulty_rating": 1150, "question_latex": "What is $\\gcd(84,126)$?", "options": [{"label": "A", "text": "7"}, {"label": "B", "text": "14"}, {"label": "C", "text": "21"}, {"label": "D", "text": "42"}, {"label": "E", "text": "63"}], "correct_answer": "D", "figure_required": false, "figure_image_path": null, "written_solution": "$126=84+42$ and $84=2\\cdot42$, so the greatest common divisor is $42$.", "calculator_trick": {"model": "Casio FX-115ES PLUS", "applicable": false, "summary": "This problem is best approached analytically.", "steps": []}, "title": "Euclidean Algorithm", "topic_tags": ["Number Theory"], "verification_status": "fully_verified", "source_question_file": null, "source_answer_key_file": null, "publication_status": "published", "difficulty": "Easy"}, {"id": "demo-11", "contest_name": "Original Demonstration Set", "question_number": 11, "category": "Geometry", "difficulty_rating": 1100, "question_latex": "A circle has circumference $12\\pi$. What is its area?", "options": [{"label": "A", "text": "$12\\pi$"}, {"label": "B", "text": "$18\\pi$"}, {"label": "C", "text": "$24\\pi$"}, {"label": "D", "text": "$36\\pi$"}, {"label": "E", "text": "$144\\pi$"}], "correct_answer": "D", "figure_required": false, "figure_image_path": null, "written_solution": "$2\\pi r=12\\pi$ gives $r=6$, hence area $\\pi r^2=36\\pi$.", "calculator_trick": {"model": "Casio FX-115ES PLUS", "applicable": false, "summary": "This problem is best approached analytically.", "steps": []}, "title": "Circle Area", "topic_tags": ["Geometry"], "verification_status": "fully_verified", "source_question_file": null, "source_answer_key_file": null, "publication_status": "published", "difficulty": "Easy"}, {"id": "demo-12", "contest_name": "Original Demonstration Set", "question_number": 12, "category": "Functions and Graphs", "difficulty_rating": 1200, "question_latex": "If $f(x)=2x^2-3$, find $f(-2)$.", "options": [{"label": "A", "text": "-11"}, {"label": "B", "text": "-5"}, {"label": "C", "text": "1"}, {"label": "D", "text": "5"}, {"label": "E", "text": "11"}], "correct_answer": "D", "figure_required": false, "figure_image_path": null, "written_solution": "$f(-2)=2(-2)^2-3=8-3=5$.", "calculator_trick": {"model": "Casio FX-115ES PLUS", "applicable": true, "summary": "Direct evaluation on a scientific calculator.", "steps": ["Type 2 \u00d7 (-2)\u00b2 - 3 [=] \u2192 5"]}, "title": "Evaluating a Function", "topic_tags": ["Functions and Graphs"], "verification_status": "fully_verified", "source_question_file": null, "source_answer_key_file": null, "publication_status": "published", "difficulty": "Easy"}, {"id": "demo-13", "contest_name": "Original Demonstration Set", "question_number": 13, "category": "Trigonometry and Precalculus", "difficulty_rating": 1100, "question_latex": "What is $\\log_2 32$?", "options": [{"label": "A", "text": "2"}, {"label": "B", "text": "3"}, {"label": "C", "text": "4"}, {"label": "D", "text": "5"}, {"label": "E", "text": "6"}], "correct_answer": "D", "figure_required": false, "figure_image_path": null, "written_solution": "$2^5=32$, so $\\log_2 32=5$.", "calculator_trick": {"model": "Casio FX-115ES PLUS", "applicable": true, "summary": "Direct evaluation on a scientific calculator.", "steps": ["Type log(32) \u00f7 log(2) [=] \u2192 5"]}, "title": "Logarithmic Identity", "topic_tags": ["Trigonometry and Precalculus"], "verification_status": "fully_verified", "source_question_file": null, "source_answer_key_file": null, "publication_status": "published", "difficulty": "Easy"}, {"id": "demo-14", "contest_name": "Original Demonstration Set", "question_number": 14, "category": "Probability and Combinatorics", "difficulty_rating": 1450, "question_latex": "A bag contains $3$ red and $2$ blue balls. Two are drawn without replacement. What is the probability both are red?", "options": [{"label": "A", "text": "$1/5$"}, {"label": "B", "text": "$3/10$"}, {"label": "C", "text": "$2/5$"}, {"label": "D", "text": "$3/5$"}, {"label": "E", "text": "$9/25$"}], "correct_answer": "B", "figure_required": false, "figure_image_path": null, "written_solution": "$P=\\frac35\\cdot\\frac24=\\frac3{10}$.", "calculator_trick": {"model": "Casio FX-115ES PLUS", "applicable": true, "summary": "Direct evaluation on a scientific calculator.", "steps": ["Type (3 \u00f7 5) \u00d7 (2 \u00f7 4) [=] \u2192 3/10"]}, "title": "Sampling Without Replacement", "topic_tags": ["Probability and Combinatorics"], "verification_status": "fully_verified", "source_question_file": null, "source_answer_key_file": null, "publication_status": "published", "difficulty": "Medium"}, {"id": "demo-15", "contest_name": "Original Demonstration Set", "question_number": 15, "category": "Number Theory", "difficulty_rating": 1600, "question_latex": "How many positive divisors does $72$ have?", "options": [{"label": "A", "text": "6"}, {"label": "B", "text": "8"}, {"label": "C", "text": "10"}, {"label": "D", "text": "12"}, {"label": "E", "text": "14"}], "correct_answer": "D", "figure_required": false, "figure_image_path": null, "written_solution": "$72=2^3 3^2$ gives $(3+1)(2+1)=12$ divisors.", "calculator_trick": {"model": "Casio FX-115ES PLUS", "applicable": false, "summary": "This problem is best approached analytically.", "steps": []}, "title": "Counting Divisors", "topic_tags": ["Number Theory"], "verification_status": "fully_verified", "source_question_file": null, "source_answer_key_file": null, "publication_status": "published", "difficulty": "Medium"}, {"id": "demo-16", "contest_name": "Original Demonstration Set", "question_number": 16, "category": "Geometry", "difficulty_rating": 1800, "question_latex": "A regular hexagon has side length $2$. What is its area?", "options": [{"label": "A", "text": "$3\\sqrt3$"}, {"label": "B", "text": "$6$"}, {"label": "C", "text": "$6\\sqrt3$"}, {"label": "D", "text": "$12\\sqrt3$"}, {"label": "E", "text": "$24$"}], "correct_answer": "C", "figure_required": false, "figure_image_path": null, "written_solution": "Six equilateral triangles of side $2$ each have area $\\sqrt3$, giving $6\\sqrt3$.", "calculator_trick": {"model": "Casio FX-115ES PLUS", "applicable": false, "summary": "This problem is best approached analytically.", "steps": []}, "title": "Regular Hexagon", "topic_tags": ["Geometry"], "verification_status": "fully_verified", "source_question_file": null, "source_answer_key_file": null, "publication_status": "published", "difficulty": "Hard"}, {"id": "demo-17", "contest_name": "Original Demonstration Set", "question_number": 17, "category": "Algebra", "difficulty_rating": 1650, "question_latex": "If $x+1/x=3$, find $x^2+1/x^2$.", "options": [{"label": "A", "text": "5"}, {"label": "B", "text": "6"}, {"label": "C", "text": "7"}, {"label": "D", "text": "9"}, {"label": "E", "text": "11"}], "correct_answer": "C", "figure_required": false, "figure_image_path": null, "written_solution": "Squaring gives $x^2+2+1/x^2=9$, so the answer is $7$.", "calculator_trick": {"model": "Casio FX-115ES PLUS", "applicable": false, "summary": "This problem is best approached analytically.", "steps": []}, "title": "Reciprocal Identity", "topic_tags": ["Algebra"], "verification_status": "fully_verified", "source_question_file": null, "source_answer_key_file": null, "publication_status": "published", "difficulty": "Medium"}, {"id": "demo-18", "contest_name": "Original Demonstration Set", "question_number": 18, "category": "Sequences and Series", "difficulty_rating": 1550, "question_latex": "A geometric sequence starts $3,6,12,\\ldots$. What is the sum of its first six terms?", "options": [{"label": "A", "text": "93"}, {"label": "B", "text": "96"}, {"label": "C", "text": "186"}, {"label": "D", "text": "189"}, {"label": "E", "text": "192"}], "correct_answer": "D", "figure_required": false, "figure_image_path": null, "written_solution": "$S_6=3(2^6-1)/(2-1)=189$.", "calculator_trick": {"model": "Casio FX-115ES PLUS", "applicable": true, "summary": "Direct evaluation on a scientific calculator.", "steps": ["Type 3 \u00d7 (2\u2076 - 1) [=] \u2192 189"]}, "title": "Geometric Series", "topic_tags": ["Sequences and Series"], "verification_status": "fully_verified", "source_question_file": null, "source_answer_key_file": null, "publication_status": "published", "difficulty": "Medium"}, {"id": "demo-19", "contest_name": "Original Demonstration Set", "question_number": 19, "category": "Probability and Combinatorics", "difficulty_rating": 1250, "question_latex": "How many distinct arrangements are there of the letters in MATH?", "options": [{"label": "A", "text": "8"}, {"label": "B", "text": "12"}, {"label": "C", "text": "16"}, {"label": "D", "text": "24"}, {"label": "E", "text": "32"}], "correct_answer": "D", "figure_required": false, "figure_image_path": null, "written_solution": "All four letters are distinct, so there are $4!=24$ permutations.", "calculator_trick": {"model": "Casio FX-115ES PLUS", "applicable": true, "summary": "Direct evaluation on a scientific calculator.", "steps": ["Type 4 \u00d7 3 \u00d7 2 \u00d7 1 [=] \u2192 24"]}, "title": "Letter Arrangements", "topic_tags": ["Probability and Combinatorics"], "verification_status": "fully_verified", "source_question_file": null, "source_answer_key_file": null, "publication_status": "published", "difficulty": "Easy"}, {"id": "demo-20", "contest_name": "Original Demonstration Set", "question_number": 20, "category": "Number Theory", "difficulty_rating": 1900, "question_latex": "Find the least positive integer $n$ such that $n\\equiv2\\pmod3$ and $n\\equiv3\\pmod5$.", "options": [{"label": "A", "text": "3"}, {"label": "B", "text": "5"}, {"label": "C", "text": "8"}, {"label": "D", "text": "13"}, {"label": "E", "text": "23"}], "correct_answer": "C", "figure_required": false, "figure_image_path": null, "written_solution": "The positive integers congruent to $3$ modulo $5$ begin $3,8,13$. The first also congruent to $2$ modulo $3$ is $8$.", "calculator_trick": {"model": "Casio FX-115ES PLUS", "applicable": false, "summary": "This problem is best approached analytically.", "steps": []}, "title": "Modular Conditions", "topic_tags": ["Number Theory"], "verification_status": "fully_verified", "source_question_file": null, "source_answer_key_file": null, "publication_status": "published", "difficulty": "Hard"}]$seed$::jsonb,true);
